"""Exact deterministic SyncWise extension: calibration, planning, audit, replay.

All arithmetic is exact integer arithmetic.  Time-like quantities are converted
to attoseconds (as): 1 ps = 10^6 as, 1 ns = 10^9 as.  A drift of v ppb over
t ns contributes v*t as.
"""
import heapq
import json
import math

AS_PER_PS = 10 ** 6
AS_PER_NS = 10 ** 9


# ---------------------------------------------------------------- calibration

class Calibration:
    """Tight port-bias ranges from noisy relative-delay constraints."""

    def __init__(self, profile):
        self.K = int(profile['groups'])
        self.jitter = [int(x) for x in profile['jitter_ps']]
        self.meas = []
        for m in profile['measurements']:
            self.meas.append((int(m[0]), int(m[1]), int(m[2]), int(m[3])))
        self.m = len(self.meas)
        edges = []
        for i, (a, b, lo, hi) in enumerate(self.meas):
            edges.append((a, b, hi, 2 * i))
            edges.append((b, a, -lo, 2 * i + 1))
        self.edges = edges
        out = [[] for _ in range(self.K)]
        for e in edges:
            out[e[0]].append(e)
        self.out = out
        self.cycle = self._negative_cycle()
        if self.cycle is None:
            self._solve_distances()
            self._solve_pred()
            self._solve_hop()
        else:
            self.upper = None
            self.pred = None
            self.hop = None
            self.corr = None

    # -- inconsistency -------------------------------------------------
    def _negative_cycle(self):
        K = self.K
        edges = self.edges
        dist = [0] * K
        pv = [-1] * K
        pc = [-1] * K
        for _ in range(K):
            updated = False
            for (u, v, w, cid) in edges:
                nd = dist[u] + w
                if nd < dist[v]:
                    dist[v] = nd
                    pv[v] = u
                    pc[v] = cid
                    updated = True
            if not updated:
                return None
        # a negative cycle exists; locate one in the predecessor graph
        state = [0] * K
        for s in range(K):
            if state[s]:
                continue
            path = []
            pos = {}
            z = s
            while z != -1 and state[z] == 0:
                pos[z] = len(path)
                path.append(z)
                z = pv[z]
            if z != -1 and z in pos:
                cyc = path[pos[z]:]
                tot = 0
                for node in cyc:
                    tot += edges[pc[node]][2]
                if tot < 0:
                    return self._order_cycle(cyc, pv, pc)
            for node in path:
                state[node] = 2
        # unreachable in practice; search every predecessor cycle
        for s in range(K):
            if state[s] == 2:
                continue
        return None

    @staticmethod
    def _order_cycle(cyc, pv, pc):
        nxt = {}
        cid_of = {}
        for node in cyc:
            src = pv[node]
            nxt[src] = node
            cid_of[src] = pc[node]
        out = []
        z = cyc[0]
        for _ in range(len(cyc)):
            out.append(cid_of[z])
            z = nxt[z]
        return out

    # -- tight suprema --------------------------------------------------
    def _solve_distances(self):
        import numpy as np
        K = self.K
        BIG = 1 << 60
        dist = np.full((K, K), BIG, dtype=np.int64)
        for a in range(K):
            dist[a, a] = 0
        for (u, v, w, cid) in self.edges:
            if w < dist[u, v]:
                dist[u, v] = w
        for k in range(K):
            cand = dist[:, k].reshape(K, 1) + dist[k, :].reshape(1, K)
            np.minimum(dist, cand, out=dist)
        self.upper = [[int(dist[a, b]) for b in range(K)] for a in range(K)]

    def _solve_pred(self):
        K = self.K
        upper = self.upper
        out = self.out
        pred = [[None] * K for _ in range(K)]
        for a in range(K):
            row = pred[a]
            da = upper[a]
            visited = [False] * K
            visited[a] = True
            stack = [a]
            while stack:
                u = stack.pop()
                du = da[u]
                for (uu, v, w, cid) in out[u]:
                    if not visited[v] and du + w == da[v]:
                        visited[v] = True
                        row[v] = cid
                        stack.append(v)
        self.pred = pred

    def _solve_hop(self):
        K = self.K
        upper = self.upper
        self.hop = [[0] * K for _ in range(K)]
        self.corr = [[0] * K for _ in range(K)]
        for a in range(K):
            for b in range(K):
                uab = upper[a][b]
                uba = upper[b][a]
                self.corr[a][b] = (uab - uba) * 500000
                self.hop[a][b] = ((uab + uba) * 500000
                                  + (self.jitter[a] + self.jitter[b]) * AS_PER_PS)

    def constraint(self, cid):
        return self.edges[cid]

    def artifact(self):
        if self.cycle is not None:
            return {"status": "inconsistent", "cycle": list(self.cycle)}
        return {"status": "ok",
                "upper_ps": [list(r) for r in self.upper],
                "pred": [list(r) for r in self.pred]}
