# ------------------------------------------------------------ model + caches

class Model:
    def __init__(self, profile, fabric):
        self.cal = Calibration(profile)
        self.F = None
        self._bounds = {}
        self._full = {}
        if self.cal.cycle is None:
            F = Fabric(fabric)
            F.build_edges(self.cal)
            self.F = F

    def bounds_for(self, g):
        d = self._bounds.get(g)
        if d is None:
            d = solve_bounds(self.F, g)
            self._bounds[g] = d
        return d

    def full_for(self, g):
        d = self._full.get(g)
        if d is None:
            d = solve_full(self.F, g)
            self._full[g] = d
        return d


_CAL_CACHE = {}
_MODEL_CACHE = {}


def cal_key(profile):
    return json.dumps(profile, sort_keys=True)


def get_model(profile, fabric):
    key = (cal_key(profile), json.dumps(fabric, sort_keys=True))
    m = _MODEL_CACHE.get(key)
    if m is None:
        m = Model(profile, fabric)
        _MODEL_CACHE[key] = m
    return m


def peak_of(F, dist):
    if any(d is None for d in dist):
        return None
    return max(dist[c] + F.drift_as[c] for c in range(F.V))


def select_guard(F, peaks):
    for idx, g in enumerate(F.guards):
        pk = peaks[idx]
        if pk is not None and g * AS_PER_NS >= pk + F.r * AS_PER_NS:
            return g
    return None


def warmup_of(M, g):
    dist, pred = M.full_for(g)
    F = M.F
    N, P = F.N, F.P
    worst = 0
    for c in range(F.V):
        d = dist[c]
        if d is None:
            return None
        k = (d[2] - c // N) // P
        if k > worst:
            worst = k
    return worst


def plan_peaks(M):
    F = M.F
    return [peak_of(F, M.bounds_for(g)) for g in F.guards]


# --------------------------------------------------------------- operations

def op_calibrate(profile):
    return Calibration(profile).artifact()


def op_plan(profile, fabric):
    M = get_model(profile, fabric)
    cal = M.cal
    if cal.cycle is not None:
        return {"status": "inconsistent", "cycle": list(cal.cycle)}
    F = M.F
    peaks = plan_peaks(M)
    guard = select_guard(F, peaks)
    out = {"status": "ok", "profile": cal.artifact(),
           "period_rounds": F.P, "peaks_as": peaks, "guard_ns": guard,
           "bounds_as": None, "age_rounds": None, "pred": None,
           "warmup_cycle": None}
    if guard is not None:
        dist, pred = M.full_for(guard)
        N, P = F.N, F.P
        bounds_rows = []
        age_rows = []
        pred_rows = []
        for p in range(P):
            br = []
            ar = []
            pr = []
            base = p * N
            for i in range(N):
                d = dist[base + i]
                if d is None:
                    br.append(None)
                    ar.append(None)
                    pr.append(None)
                else:
                    br.append(d[0])
                    ar.append(d[1])
                    pv = pred[base + i]
                    pr.append(None if pv is None else [pv[0], pv[1]])
            bounds_rows.append(br)
            age_rows.append(ar)
            pred_rows.append(pr)
        out["bounds_as"] = bounds_rows
        out["age_rounds"] = age_rows
        out["pred"] = pred_rows
        out["warmup_cycle"] = warmup_of(M, guard)
    return out
