"""JSONL driver for the extended SyncWise computational system."""
import json
import sys

import engine


def dispatch(req):
    op = req['op']
    if op == 'calibrate':
        return engine.op_calibrate(req['profile'])
    if op == 'plan':
        return engine.op_plan(req['profile'], req['fabric'])
    if op == 'audit':
        return engine.op_audit(req['profile'], req['fabric'], req['proposal'])
    return engine.op_replay(req['profile'], req['fabric'], req['guard_ns'],
                            req['trace'])


def main():
    out = sys.stdout
    for line in sys.stdin:
        if line.strip():
            resp = dispatch(json.loads(line))
            out.write(json.dumps(resp, separators=(',', ':')) + '\n')
            out.flush()


if __name__ == '__main__':
    main()
