import random, sys, json, copy
sys.path.insert(0,'/workspace/tmp')
from tlib import run
from tplan import Brute
from test_plan import gen_case

def alt_witness(prof, fab, plan):
    """Build a certificate with different (still optimal) predecessor choices."""
    b=Brute(prof,fab); g=plan['guard_ns']
    P,N=b.P,b.N
    env=b.envelope(g)
    Lb={(p,i):env[(p,i)][0] for p in range(P) for i in range(N)}
    La={(p,i):env[(p,i)][1] for p in range(P) for i in range(N)}
    pred=[[None]*N for _ in range(P)]
    # BFS over tight edges from anchors, but visit nodes in reversed order to
    # pick different optimal predecessors
    from collections import deque
    reach={}
    q=deque()
    for p in range(P):
        for i in range(N):
            if b.anchored[p][i]:
                reach[(p,i)]=True; q.append((p,i))
    order=[]
    while q:
        cur=q.popleft(); order.append(cur)
        p,i=cur
        for (dn,dp,dt,cost) in b.steps(p,i,g):
            if Lb[(dp,dn)]==Lb[cur]+cost and La[(dp,dn)]==La[cur]+dt and (dp,dn) not in reach:
                reach[(dp,dn)]=True
                q.append((dp,dn))
    # assign preds: for each reachable non-anchor pick the LAST tight edge seen
    cand={}
    for p in range(P):
        for i in range(N):
            for (dn,dp,dt,cost) in b.steps(p,i,g):
                if (p,i) in reach and (dp,dn) in reach:
                    if Lb[(dp,dn)]==Lb[(p,i)]+cost and La[(dp,dn)]==La[(p,i)]+dt:
                        if b.anchored[dp][dn]: continue
                        # kind of this step
                        if (dn==(i) and dp==(p+1)%P and dt==1): kind=-1
                        else:
                            kind=None
                            for l,link in enumerate(b.links):
                                for d in (0,1):
                                    (n0,_,g0),(n1,_,g1),delays,defers=link
                                    src,dst=(n0,n1) if d==0 else (n1,n0)
                                    mm=(delays[d]+b.T-1)//b.T
                                    if src==i and dst==dn and mm+defers[d]==dt and (p+mm+defers[d])%P==dp:
                                        if cost==b.hop[ (g0 if d==0 else g1) ][ (g1 if d==0 else g0) ] + b.aging_cost(dst,p,delays[d],mm+defers[d]):
                                            kind=2*l+d
                        cand[(dp,dn)]=((p,i),kind)
    for p in range(P):
        for i in range(N):
            if b.anchored[p][i]:
                pred[p][i]=None
            elif (p,i) in cand:
                (u,kind)=cand[(p,i)]
                pred[p][i]=[u[0]*N+u[1],kind]
            else:
                pred[p][i]=plan['pred'][p][i]
    out=copy.deepcopy(plan)
    out['pred']=pred
    return out

# monkeypatch aging into Brute
def aging_cost(self,node,p,delay,dt):
    total=0; end=dt*self.T
    for j in range(dt):
        lo=j*self.T; hi=lo+self.T
        if lo<delay: lo=delay
        if hi>end: hi=end
        if hi>lo: total+=self.drift[(p+j)%self.P][node]*(hi-lo)
    return total
Brute.aging_cost=aging_cost

